function releaseDocumentCopy(locale, documents) {
  const bodies = releaseLegalBodies[locale] || releaseLegalBodies.en
  const replaceSections = (documentKey, source) => ({
    ...source,
    sections: source.sections.map((entry) => {
      const sectionNumber = Number.parseInt(entry.title, 10)
      return { ...entry, body: bodies[`${documentKey}${sectionNumber}`] || entry.body }
    }),
  })
  return { ...documents, eula: replaceSections('eula', documents.eula), terms: replaceSections('terms', documents.terms), privacy: replaceSections('privacy', documents.privacy) }
}

export function legalDocuments(locale) {
  const resolvedLocale = documentsByLocale[locale] ? locale : 'en'
  return releaseDocumentCopy(resolvedLocale, documentsByLocale[resolvedLocale])
}
